mapper.select:
select id, student_id, template_id, effective_start_time, effective_end_time, status, created_at, updated_at
from stu_student_permission_template
where student_id = #{studentId}
  and template_id = #{templateId}
limit 1

mapper.insert:
insert into stu_student_permission_template (
    student_id, template_id, effective_start_time, effective_end_time, status, created_at, updated_at
) values (
    #{studentId}, #{templateId}, #{effectiveStartTime}, #{effectiveEndTime}, #{status}, #{createdAt}, #{updatedAt}
)

mapper.update:
update stu_student_permission_template
set effective_start_time = #{effectiveStartTime},
    effective_end_time = #{effectiveEndTime},
    status = #{status},
    updated_at = #{updatedAt}
where id = #{id}
